<?php require_once __DIR__.'/../app/bootstrap.php';require_once __DIR__.'/../app/hcaptcha.php'; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(!hcaptcha_verify_request('register')){flash('error','Completa la verificación hCaptcha antes de registrarte.');redirect('register.php');}$u=trim($_POST['username']??'');$e=trim($_POST['email']??'');$p=$_POST['password']??'';$n=trim($_POST['display_name']??'');
if(!preg_match('/^[A-Za-z0-9_]{3,40}$/',$u)||!filter_var($e,FILTER_VALIDATE_EMAIL)||strlen($p)<8||$n===''){flash('error','Revisa los datos. Contraseña mínima: 8 caracteres.');redirect('register.php');}
$count=(int)db()->query('SELECT COUNT(*) FROM users')->fetchColumn();$role=$count===0?'admin':'user';$status=$count===0?'active':'pending';
try{db()->beginTransaction();$q=db()->prepare('INSERT INTO users(username,email,password_hash,role,status) VALUES(?,?,?,?,?)');$q->execute([$u,$e,password_hash($p,PASSWORD_DEFAULT),$role,$status]);$id=(int)db()->lastInsertId();$q=db()->prepare('INSERT INTO profiles(user_id,display_name) VALUES(?,?)');$q->execute([$id,$n]);db()->commit();flash('success',$role==='admin'?'Cuenta administradora creada.':'Cuenta creada; espera aprobación.');redirect('login.php');}catch(PDOException $x){if(db()->inTransaction())db()->rollBack();flash('error','Usuario o correo ya registrado.');redirect('register.php');}}
require __DIR__.'/../partials/header.php';?><section class="auth card"><h1>Crear cuenta</h1><form method="post"><?=csrf_field()?><label>Nombre visible<input name="display_name" required></label><label>Usuario<input name="username" required pattern="[A-Za-z0-9_]{3,40}"></label><label>Correo<input type="email" name="email" required></label><label>Contraseña<input type="password" name="password" minlength="8" required></label><?=hcaptcha_widget('register')?><button class="btn">Registrarme</button></form><p>El primer usuario será administrador. Los siguientes deberán ser aprobados.</p></section><?=hcaptcha_script('register')?><?php require __DIR__.'/../partials/footer.php';?>
